      "Condition": {"Bool": {"aws:SecureTransport": "false"}}
    },
    {
      "Effect": "Allow",
      "Principal": {"AWS": "arn:aws:iam::<acct>:role/<lambda-execution-role>"},
      "Action": "s3:PutObject",
